"""Who skips the eligibility and payment checks on course and batch enrollment."""

import frappe

from lms.lms.test_helpers import BaseTestUtils


class TestEnrollmentStaffExemption(BaseTestUtils):
	@classmethod
	def setUpClass(cls):
		super().setUpClass()
		frappe.set_user("Administrator")
		suffix = frappe.generate_hash(length=6)
		cls.instructor = cls._ese_user(suffix, "ins", ["Course Creator"])
		cls.creator = cls._ese_user(suffix, "cc", ["Course Creator"])
		cls.evaluator = cls._ese_user(suffix, "ev", ["LMS Student", "Batch Evaluator"])
		cls.batch_staff = cls._ese_user(suffix, "bs", ["Course Creator", "Batch Evaluator"])
		cls.moderator = cls._ese_user(suffix, "mod", ["Moderator"])
		cls.student = cls._ese_user(suffix, "stu", ["LMS Student"])
		cls.other_student = cls._ese_user(suffix, "stu2", ["LMS Student"])
		cls._create_evaluator(cls.batch_staff.email)

		cls.courses = {}
		for state in ("paid_course", "unpublished", "disable_self_learning"):
			course = cls._create_course(f"ESE {state} {suffix}", cls.instructor.email).name
			cls.courses[state] = course
		frappe.db.set_value(
			"LMS Course",
			cls.courses["paid_course"],
			{"paid_course": 1, "course_price": 100, "currency": "INR"},
		)
		frappe.db.set_value("LMS Course", cls.courses["unpublished"], "published", 0)
		frappe.db.set_value("LMS Course", cls.courses["disable_self_learning"], "disable_self_learning", 1)

		free_course = cls._create_course(f"ESE free {suffix}", cls.instructor.email).name
		cls.restricted_batch = cls._create_batch(
			free_course, cls.batch_staff.email, f"ESE restricted {suffix}", cls.batch_staff.email
		).name
		cls.paid_course_batch = cls._create_batch(
			cls.courses["paid_course"],
			cls.batch_staff.email,
			f"ESE paid course {suffix}",
			cls.batch_staff.email,
		).name
		all_courses_batch = cls._create_batch(
			cls.courses["paid_course"],
			cls.batch_staff.email,
			f"ESE all courses {suffix}",
			cls.batch_staff.email,
		)
		for state in ("unpublished", "disable_self_learning"):
			all_courses_batch.append(
				"courses", {"course": cls.courses[state], "evaluator": cls.batch_staff.email}
			)
		all_courses_batch.save()
		cls.all_courses_batch = all_courses_batch.name

	@classmethod
	def _ese_user(cls, suffix, prefix, roles):
		return cls._create_user(f"ese-{prefix}-{suffix}@example.com", "ESE", prefix, roles)

	def tearDown(self):
		frappe.set_user("Administrator")
		super().tearDown()

	def _enroll_in_course(self, user, course):
		frappe.set_user(user)
		doc = frappe.new_doc("LMS Enrollment")
		doc.update({"member": user, "course": course})
		doc.insert()
		return doc

	def _enroll_in_batch(self, member, batch, owner=None):
		frappe.set_user(owner or member)
		doc = frappe.new_doc("LMS Batch Enrollment")
		doc.update({"member": member, "batch": batch})
		doc.insert()
		return doc

	def test_unrelated_staff_roles_do_not_skip_course_checks(self):
		"""#1922 let any Course Creator or Batch Evaluator skip the paid, published and
		self-learning checks on every course. Added in this PR (ticket 78761)."""
		refusals = {
			"paid_course": "complete the payment",
			"unpublished": "unpublished course",
			"disable_self_learning": "self-learning is disabled",
		}
		for user in (self.creator, self.evaluator):
			for state, refusal in refusals.items():
				with self.subTest(user=user.email, state=state):
					with self.assertRaisesRegex(frappe.ValidationError, refusal):
						self._enroll_in_course(user.email, self.courses[state])

	def test_course_instructor_and_moderator_skip_course_checks(self):
		"""Narrowing #1922's role list must keep the course's own staff exempt. Added in this PR."""
		for user in (self.instructor, self.moderator):
			for state, course in self.courses.items():
				with self.subTest(user=user.email, state=state):
					self.assertEqual(self._enroll_in_course(user.email, course).member, user.email)

	def test_unrelated_staff_roles_cannot_self_enroll_in_restricted_batch(self):
		"""#1937 let any Course Creator or Batch Evaluator self-enroll in a batch closed
		to self-enrollment. Added in this PR (ticket 78761)."""
		for user in (self.creator, self.evaluator):
			with self.subTest(user=user.email):
				with self.assertRaisesRegex(frappe.ValidationError, "restricted"):
					self._enroll_in_batch(user.email, self.restricted_batch)

	def test_batch_staff_self_enroll_in_restricted_batch(self):
		"""Narrowing #1937's role list must keep the batch's tagged staff exempt. Added in this PR."""
		doc = self._enroll_in_batch(self.batch_staff.email, self.restricted_batch)
		self.assertEqual(doc.member, self.batch_staff.email)

	def test_batch_evaluator_enrolls_others_through_a_batch(self):
		"""Enrolling someone else stays with validate_owner, and the batch's course rows
		must not refuse its paid course. Added in this PR."""
		for batch in (self.restricted_batch, self.paid_course_batch):
			with self.subTest(batch=batch):
				doc = self._enroll_in_batch(self.student.email, batch, owner=self.evaluator.email)
				self.assertEqual(doc.member, self.student.email)

	def test_client_cannot_enroll_another_member(self):
		frappe.set_user(self.student.email)
		with self.assertRaises(frappe.PermissionError):
			frappe.client.insert(
				{
					"doctype": "LMS Enrollment",
					"member": self.other_student.email,
					"course": self.courses["paid_course"],
					"enrollment_from_batch": self.all_courses_batch,
				}
			)

	def test_client_flags_cannot_skip_course_checks(self):
		"""via_batch_enrollment is set only by the server; a client insert carrying it still gets the course checks."""
		refusals = {
			"paid_course": "complete the payment",
			"unpublished": "unpublished course",
			"disable_self_learning": "self-learning is disabled",
		}
		frappe.set_user(self.student.email)
		for state, refusal in refusals.items():
			with self.subTest(state=state):
				with self.assertRaisesRegex(frappe.ValidationError, refusal):
					frappe.client.insert(
						{
							"doctype": "LMS Enrollment",
							"member": self.student.email,
							"course": self.courses[state],
							"enrollment_from_batch": self.all_courses_batch,
							"flags": {"via_batch_enrollment": True},
						}
					)

import frappe

from lms.lms.test_helpers import BaseTestUtils


class TestEnrollmentFieldGuard(BaseTestUtils):
	"""A student must not be able to write the server-managed progress /
	purchased_certificate fields on their own enrollment
	(VULN-2026-FRAPPE-LMS-009, -010)."""

	@classmethod
	def setUpClass(cls):
		super().setUpClass()
		hash = frappe.generate_hash(length=6)
		cls.student = cls._create_user(f"efstud-{hash}@example.com", "Eli", "Student", ["LMS Student"])
		cls.moderator = cls._create_user(f"efmod-{hash}@example.com", "Mac", "Derator", ["Moderator"])
		cls.course = cls._create_course(title=f"Guard Course {hash}", instructor=cls.moderator.email)
		cls.enrollment = cls._create_enrollment(cls.student.email, cls.course.name)

	def _as(self, user, mutate):
		frappe.session.user = user
		try:
			doc = frappe.get_doc("LMS Enrollment", self.enrollment.name)
			mutate(doc)
			doc.save()
		finally:
			frappe.session.user = "Administrator"

	def _stored(self, field):
		return frappe.db.get_value("LMS Enrollment", self.enrollment.name, field)

	def test_student_cannot_set_progress(self):
		def mutate(doc):
			doc.progress = 100

		self._as(self.student.email, mutate)
		self.assertEqual(self._stored("progress"), 0)

	def test_student_cannot_set_purchased_certificate(self):
		def mutate(doc):
			doc.purchased_certificate = 1

		self._as(self.student.email, mutate)
		self.assertEqual(self._stored("purchased_certificate"), 0)

	def test_moderator_can_set_progress(self):
		def mutate(doc):
			doc.progress = 100

		self._as(self.moderator.email, mutate)
		self.assertEqual(self._stored("progress"), 100)

	def test_server_side_set_value_still_writes_progress(self):
		# The legitimate write path (update_enrollment / update_certificate_purchase) uses
		# frappe.db.set_value, which bypasses validate() and must remain unaffected.
		frappe.db.set_value("LMS Enrollment", self.enrollment.name, "progress", 55)
		self.assertEqual(self._stored("progress"), 55)

import { format } from 'node:util'
import { afterAll, afterEach, beforeAll, vi } from 'vitest'
import type { VueWrapper } from '@vue/test-utils'

// main.js puts `__` on window; without it a script-block translation dies on a
// bare ReferenceError. Mirrors translate(), including the contract that a
// message with {0} returns a { format } object rather than a string.
vi.stubGlobal('__', (message: string) => {
	if (!/{\d+}/.test(message)) return message
	return {
		format: (...args: unknown[]) =>
			message.replace(/{(\d+)}/g, (match, index) =>
				args[Number(index)] === undefined ? match : String(args[Number(index)])
			),
	}
})

// face-api.js bundles TensorFlow, which under jsdom sees both a window and a
// process, registers a browser and then a node platform, and warns about the
// second. Nothing here runs a model; proctoringMonitor.test.ts mocks its own.
vi.mock('face-api.js', () => ({
	nets: { tinyFaceDetector: { loadFromUri: async () => {} } },
	detectAllFaces: async () => [],
	TinyFaceDetectorOptions: class {},
}))

// A test that prints is a test with a problem nobody is looking at: a Vue
// warning, a missing stub, a rejected promise caught and logged. Every console
// call is recorded instead of printed and fails the test that made it. A test
// that expects output spies on the method itself, which replaces this recorder
// for that test only.
//
// The allow-list is for output a test cannot fix. Each entry names its source;
// the app ones are bugs to fix, after which the entry goes.
const ALLOWED = [
	// reka-ui's dev check on frappe-ui's Dialog, which sets aria-describedby
	// even when it renders no DialogDescription.
	/^Warning: Missing `Description` or `aria-describedby="undefined"` for DialogContent\.$/,
	// App: EditorJS's built-in paragraph tool and the markdown tool both claim
	// pasted <p>, so markdown never receives one.
	/^Paste handler for «markdown» Tool on «P» tag is skipped because it is already used by «paragraph» Tool\.$/,
	// App: ProgrammingExerciseForm declares exerciseID required, and the
	// /programming-exercises/new route passes none.
	/^\[Vue warn\]: Missing required prop: "exerciseID"/,
	// App: ExerciseConsole's hint combo "Mod+`" should name the key, "Mod+Backtick".
	/^\[frappe-ui\] "`" in the combo "Mod\+`" is not a key name/,
	// App: NewCourseForm starts course.image as undefined, and Uploader's
	// modelValue takes a string or null.
	/^\[Vue warn\]: Invalid prop: type check failed for prop "modelValue"\. Expected String \| Null, got Undefined[\s\S]*<NewCourseForm/,
	// App: the /quiz-submissions/:quizID redirect names a route with no quizID
	// param, and the router drops the one it carries over.
	/^\[Vue Router warn\]: Discarded invalid param\(s\) "quizID" when navigating/,
]

const printed: string[] = []
for (const method of ['error', 'warn', 'log', 'info', 'debug'] as const) {
	console[method] = (...args: unknown[]) => {
		const line = format(...args)
		if (!ALLOWED.some((pattern) => pattern.test(line))) {
			printed.push(`console.${method}: ${line}`)
		}
	}
}

const assertSilent = (when: string) => {
	if (!printed.length) return
	const lines = printed.splice(0)
	throw new Error(`${when} printed to the console:\n${lines.join('\n')}`)
}

// Registered first so it runs last, after every cleanup hook below and in the
// test file has had its chance to warn.
afterEach(() => assertSilent('This test'))
beforeAll(() => assertSilent('Importing this file'))
afterAll(() => assertSilent('A hook in this file'))

afterEach(() => {
	vi.restoreAllMocks()
	vi.useRealTimers()
})

if (typeof window !== 'undefined') {
	const { config } = await import('@vue/test-utils')
	const { safeHtml, vExternal } = await import('../directives')

	// main.js registers these on the app, so a component that uses one renders
	// wrong under a bare mount() and the failure looks like missing data rather
	// than a missing directive. Registering them here keeps component tests
	// rendering what the app renders. Skipped under `@vitest-environment node`,
	// where nothing mounts and DOMPurify has no window to bind to.
	config.global.directives = {
		...config.global.directives,
		'safe-html': safeHtml,
		external: vExternal,
	}

	// Unmounts whatever a test left mounted. VTU's enableAutoUnmount cannot be
	// used here: it unmounts unconditionally, and a test that already unmounted
	// its wrapper would then make Vue warn about unmounting an unmounted app.
	const roots: VueWrapper[] = []
	config.plugins.VueWrapper.install((wrapper) => {
		if ((wrapper as unknown as { __app: unknown }).__app) roots.push(wrapper)
		return {}
	})

	// Globals a test replaces with Object.defineProperty or a plain assignment,
	// which vi.restoreAllMocks does not undo. Snapshotted after the file's own
	// module-level setup has run, so a file-wide polyfill survives.
	const STUBBED = [
		'innerWidth',
		'innerHeight',
		'matchMedia',
		'open',
		'requestAnimationFrame',
		'cancelAnimationFrame',
		'ResizeObserver',
		'IntersectionObserver',
	]
	let globals: Record<string, PropertyDescriptor | undefined> = {}
	let href = ''
	const attributes = (el: Element) =>
		Array.from(el.attributes, ({ name, value }) => [name, value] as const)
	let htmlAttributes: (readonly [string, string])[] = []
	let bodyAttributes: (readonly [string, string])[] = []

	beforeAll(() => {
		globals = Object.fromEntries(
			STUBBED.map((key) => [key, Object.getOwnPropertyDescriptor(window, key)])
		)
		href = window.location.href
		htmlAttributes = attributes(document.documentElement)
		bodyAttributes = attributes(document.body)
	})

	const restoreAttributes = (
		el: Element,
		saved: (readonly [string, string])[]
	) => {
		for (const { name } of Array.from(el.attributes)) el.removeAttribute(name)
		for (const [name, value] of saved) el.setAttribute(name, value)
	}

	afterEach(() => {
		for (const wrapper of roots.splice(0)) {
			if (!wrapper.vm?.$.isUnmounted) wrapper.unmount()
		}
		document.body.innerHTML = ''
		restoreAttributes(document.documentElement, htmlAttributes)
		restoreAttributes(document.body, bodyAttributes)
		localStorage.clear()
		sessionStorage.clear()
		if (window.location.href !== href)
			window.history.replaceState(null, '', href)
		for (const [key, descriptor] of Object.entries(globals)) {
			if (descriptor) Object.defineProperty(window, key, descriptor)
			else delete (window as unknown as Record<string, unknown>)[key]
		}
	})
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import postcss from 'postcss'
import { semanticColors } from 'frappe-ui/tailwind/tokens'
import { oklchToHex } from './oklch'

// The bug this guards: the document is painted from --surface-base, and that
// only resolves dark once <html data-theme="dark"> exists. Until this branch
// the attribute was set by src/utils/theme.ts, which cannot run before the app
// bundle executes. Measured on a production build at 390px with the bundle
// blocked — that is exactly the state the browser paints once the stylesheet
// arrives — the document came back srgb(255,255,255), and the bundle landed
// roughly 300ms after first paint (1.1s at 6x CPU throttle). Every cold load in
// dark mode therefore opened on a full-screen white flash.
//
// A test asserting that index.html contains a theme script would pass against a
// script that resolves the wrong value, or one placed after the stylesheet. So
// this suite runs the real bootstrap and then resolves the colour the document
// would actually be painted: it reads the background declaration out of
// index.css and substitutes the theme variable with the hex frappe-ui's own
// token data gives it under whichever theme the bootstrap chose.

const ROOT = resolve(__dirname, '../..')

const themeVariables = (theme: 'light' | 'dark'): Record<string, string> => {
	const out: Record<string, string> = {}
	for (const [group, tokens] of Object.entries(semanticColors[theme])) {
		for (const [name, value] of Object.entries<string>(tokens)) {
			// frappe-ui exports these as oklch(...) strings; normalize to hex once,
			// here, so every downstream comparison stays hex-only.
			out[`--${group}-${name}`] = oklchToHex(value)
		}
	}
	return out
}

const documentBackground = (): string => {
	const css = readFileSync(resolve(ROOT, 'src/index.css'), 'utf8')
	let value: string | undefined
	postcss.parse(css).walkRules((rule) => {
		if (
			!rule.selectors.some((s) => ['html', ':root', 'body'].includes(s.trim()))
		)
			return
		rule.walkDecls('background-color', (decl) => {
			value = decl.value
		})
	})
	if (!value) throw new Error('index.css paints no document background')
	return value
}

// The colour the browser would paint the canvas under a given data-theme. An
// absent attribute is `null` — the untreated first-paint state.
const paintedDocument = (theme: string | null): string =>
	documentBackground().replace(
		/var\((--[\w-]+)\)/g,
		(_, name) => themeVariables(theme === 'dark' ? 'dark' : 'light')[name]
	)

const html = readFileSync(resolve(ROOT, 'index.html'), 'utf8')

const bootstrapSource = (): string => {
	const scripts = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map(
		(match) => match[1]
	)
	const source = scripts.find((body) => body.includes('data-theme'))
	if (!source) throw new Error('index.html has no data-theme bootstrap')
	return source
}

type Scenario = {
	stored: Record<string, string>
	systemDark: boolean
}

const mediaQueryList = (query: string, systemDark: boolean) => ({
	matches: query.includes('dark') && systemDark,
	addEventListener: () => {},
	removeEventListener: () => {},
})

// Runs the real inline script against a stand-in document, and reports the
// data-theme it set — or null when it set none.
const runBootstrap = ({ stored, systemDark }: Scenario): string | null => {
	let attribute: string | null = null
	const documentStub = {
		documentElement: {
			setAttribute: (name: string, value: string) => {
				if (name === 'data-theme') attribute = value
			},
		},
	}
	const windowStub = {
		matchMedia: (query: string) => mediaQueryList(query, systemDark),
	}
	const storageStub = { getItem: (key: string) => stored[key] ?? null }
	new Function('window', 'document', 'localStorage', bootstrapSource())(
		windowStub,
		documentStub,
		storageStub
	)
	return attribute
}

// What src/utils/theme.ts resolves for the same inputs, imported fresh so its
// module-scope resolution re-runs.
const runComposable = async ({
	stored,
	systemDark,
}: Scenario): Promise<string> => {
	localStorage.clear()
	for (const [key, value] of Object.entries(stored))
		localStorage.setItem(key, value)
	vi.stubGlobal('matchMedia', (query: string) =>
		mediaQueryList(query, systemDark)
	)
	vi.resetModules()
	const module = await import('../utils/theme')
	return module.theme.value
}

afterEach(() => {
	vi.unstubAllGlobals()
	localStorage.clear()
	document.documentElement.removeAttribute('data-theme')
})

describe('the theme applied before first paint', () => {
	it('leaves the document white when nothing sets data-theme', () => {
		expect(paintedDocument(null)).toBe('#ffffff')
	})

	it('paints the canvas dark for a dark visitor with no stored preference', () => {
		const theme = runBootstrap({ stored: {}, systemDark: true })

		expect(theme).toBe('dark')
		expect(paintedDocument(theme)).toBe('#171717')
	})

	it('honours an explicit dark choice made on a light system', () => {
		const theme = runBootstrap({
			stored: { themePreference: 'dark' },
			systemDark: false,
		})

		expect(theme).toBe('dark')
		expect(paintedDocument(theme)).toBe('#171717')
	})

	it('honours an explicit light choice made on a dark system', () => {
		const theme = runBootstrap({
			stored: { themePreference: 'light' },
			systemDark: true,
		})

		expect(theme).toBe('light')
		expect(paintedDocument(theme)).toBe('#ffffff')
	})

	it('carries over the legacy single-key choice of an existing user', () => {
		const theme = runBootstrap({ stored: { theme: 'dark' }, systemDark: false })

		expect(theme).toBe('dark')
		expect(paintedDocument(theme)).toBe('#171717')
	})

	// The rules are stated twice — once inline, once in the composable — because
	// nothing that imports can run before the stylesheet paints. This is what
	// keeps the two copies from drifting.
	it('resolves exactly what src/utils/theme.ts resolves', async () => {
		const scenarios: Scenario[] = [
			{ stored: {}, systemDark: true },
			{ stored: {}, systemDark: false },
			{ stored: { themePreference: 'dark' }, systemDark: false },
			{ stored: { themePreference: 'light' }, systemDark: true },
			{ stored: { themePreference: 'system' }, systemDark: true },
			{ stored: { theme: 'dark' }, systemDark: false },
			{ stored: { theme: 'light' }, systemDark: true },
			{ stored: { themePreference: 'nonsense' }, systemDark: true },
		]

		for (const scenario of scenarios) {
			expect(runBootstrap(scenario)).toBe(await runComposable(scenario))
		}
	})

	// Placed in <head>, ahead of the stylesheet vite injects at the end of it, so
	// the attribute is already there when the first paint is unblocked.
	it('runs in the head, before anything that can paint', () => {
		const head = html.slice(html.indexOf('<head>'), html.indexOf('</head>'))

		expect(head).toContain(bootstrapSource())
	})
})
